import{state,setState}from"./state.js";import{addChild,loadDataFromServer,savePreference}from"./api.js";import{normalizeServerData}from"./server-contract.js";import{renderAll}from"./ui.js";import{showToast,closeModal,openModal}from"./utils.js";import{refreshChildLinkInline}from"./admin-settings.js";import{useChildTheme}from"./age-theme.js";function getNumericLimit(e,t){const i=Number(e);return Number.isFinite(i)?i:t}function getMonthlyLimit(e){return getNumericLimit(e?.monthlyLimit,1e4)}function getDailyLimit(e){return getNumericLimit(e?.dailyCoinLimit,0)}function updateSettingsFields(e){const t={"settings-child-name-inline":e.name,"settings-child-monthly-limit-inline":getMonthlyLimit(e),"settings-child-day-coin-limit-inline":getDailyLimit(e)};Object.keys(t).forEach(e=>{const i=document.getElementById(e);i&&(i.value=t[e])})}function applyServerChildScope(e,t){const i=normalizeServerData(e),n=i.children.length>0?i.children:state.children,a=n.find(e=>e.id==t?.id)||t;return setState({balance:i.balance??a?.balance??0,tasks:i.tasks,shopItems:i.shop,history:i.history,requests:i.requests,friends:Array.isArray(i.friends)?i.friends:[],children:n,childNickname:i.childNickname??a?.name??null,monthlyLimit:getMonthlyLimit(a),dailyCoinLimit:getDailyLimit(a)}),a}function persistPreferenceIfNeeded(e,t){!1!==t?.persistPreference&&savePreference("lastSelectedChildId",e)}function setPreSwitchState(e,t){setState({currentChildId:e,balance:t?.balance||0,monthlyLimit:getMonthlyLimit(t),dailyCoinLimit:getDailyLimit(t),childNickname:t?.name??state.childNickname}),localStorage.setItem("earnit-last-child-id",e)}async function fetchAndApplyServerData(e,t){const i=await loadDataFromServer(e);return i?applyServerChildScope(i,t):null}function handleLoadFailure(e){setState(e),renderAll(),showToast("Не удалось переключить ребенка","error")}function maybeLoadAnalytics(){const e=document.getElementById("analytics-section");e&&!e.classList.contains("hidden")&&import("./analytics-ui.js").then(e=>e.loadAnalytics())}export async function switchChild(e,t={}){if(!e)return!1;let i=state.children.find(t=>t.id==e);const n={currentChildId:state.currentChildId,balance:state.balance,monthlyLimit:state.monthlyLimit,dailyCoinLimit:state.dailyCoinLimit,childNickname:state.childNickname};setPreSwitchState(e,i),persistPreferenceIfNeeded(e,t);const a=await fetchAndApplyServerData(e,i);return a?(i=a,renderAll(),maybeLoadAnalytics(),i&&(updateSettingsFields(i),refreshChildLinkInline()),useChildTheme(e,i?.theme),!0):(handleLoadFailure(n),!1)}export function openAddChildModal(){document.getElementById("new-child-name").value="",openModal("add-child-modal")}export async function saveNewChild(){const e=document.getElementById("new-child-name").value.trim();if(!e)return showToast("Введите имя","error");const t=await addChild(e);t.success?(showToast("Ребенок добавлен!","success"),closeModal("add-child-modal"),window.location.reload()):showToast("Ошибка: "+(t.error||"Не удалось добавить"),"error")}